style.css:
/* Faculdade */
div[aria-label*="Aulas"] {
    background-color: #A8D0E6 !important; /* azul pastel */
    border-radius: 6px !important;
}

/* Deslocamento */
div[aria-label*="Deslocamento"] {
    background-color: #E0E0E0 !important; /* cinza claro */
    border-radius: 6px !important;
}

/* Pausa / Chegada / Lanche */
div[aria-label*="Pausa"],
div[aria-label*="Chegada"],
div[aria-label*="Banho"],
div[aria-label*="Lanche"] {
    background-color: #F0EAD6 !important; /* bege pastel */
    border-radius: 6px !important;
}

/* Academia */
div[aria-label*="Academia"] {
    background-color: #B8E0D2 !important; /* verde pastel */
    border-radius: 6px !important;
}

/* Teste neuro */
div[aria-label*="Teste neuro"] {
    background-color: #FFB085 !important; /* laranja pastel */
    border-radius: 6px !important;
}

/* Estudo / Revisão / TCC */
div[aria-label*="Estudo"],
div[aria-label*="Revisão"],
div[aria-label*="TCC"],
div[aria-label*="Leitura"] {
    background-color: #FFF3B0 !important; /* amarelo pastel */
    border-radius: 6px !important;
}

/* Trabalho */
div[aria-label*="Trabalho"] {
    background-color: #FFB0C2 !important; /* rosa pastel */
    border-radius: 6px !important;
}

/* Treino */
div[aria-label*="Treino"] {
    background-color: #B8D0E0 !important; /* azul suave */
    border-radius: 6px !important;
}

/* Ritbox */
div[aria-label*="Ritbox"] {
    background-color: #DCC6E0 !important; /* lilás pastel */
    border-radius: 6px !important;
}

/* Step + Ritbox */
div[aria-label*="Step"] {
    background-color: #E0C6B0 !important; /* marrom claro pastel */
    border-radius: 6px !important;
}

/* Aula de inglês */
div[aria-label*="inglês"] {
    background-color: #A8E0E6 !important; /* azul clarinho */
    border-radius: 6px !important;
}

/* Lazer / Descanso */
div[aria-label*="Lazer"],
div[aria-label*="Descanso"] {
    background-color: #DCC6E0 !important; /* lilás suave */
    border-radius: 6px !important;
}
